    text-decoration: none;
  }
  .nav-logo-main {
    font-family: var(--font-display);
    font-size: 18px;
    font-weight: 700;
    color: var(--primary);
    letter-spacing: 0.05em;
    line-height: 1.1;
  }
  .nav-logo-sub {
    font-size: 10px;
    color: rgba(255,255,255,0.65);
    letter-spacing: 0.12em;
    text-transform: uppercase;
    font-weight: 400;
  }
  .nav-links {
    display: flex;
    align-items: center;
    gap: 6px;
    list-style: none;
  }
  .nav-links a {
    color: rgba(255,255,255,0.88);
    text-decoration: none;
    font-size: 14px;
    font-weight: 500;
    padding: 8px 16px;
    border-radius: 4px;
    transition: background 0.2s, color 0.2s;
    font-family: var(--font-body);
    letter-spacing: 0.03em;
  }
  .nav-links a:hover {
    background: rgba(255,255,255,0.15);
    color: #fff;
  }
  .nav-links a.active {
    background: var(--primary);
    color: var(--secondary-dark);
    font-weight: 600;
  }
  .nav-cta {
    background: var(--primary) !important;
    color: var(--secondary-dark) !important;
    font-weight: 600 !important;
    border-radius: 4px;
  }
  .nav-cta:hover {
    background: var(--primary-dark) !important;
    color: var(--secondary-dark) !important;
  }

  /* ── HERO ── */
  .hero {
    position: relative;
    min-height: 520px;
    display: flex;
    align-items: center;
    overflow: hidden;
    background: var(--secondary-dark);
  }
  .hero-bg {
    position: absolute;
    inset: 0;
    background-image: url('http://www.siamporntrade.com/template/lib_images/submenu_image/sub_menu37.png');
    background-size: cover;
    background-position: center;
    opacity: 0.09;
  }
  .hero-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(120deg, var(--secondary-dark) 55%, rgba(92,0,0,0.65) 100%);
  }
  .hero-content {
    position: relative;
    z-index: 2;
    max-width: 1800px;
    margin: 0 auto;
    padding: 80px 24px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: center;
    width: 100%;
  }
  .hero-text {}
  .hero-eyebrow {
    display: inline-block;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: rgba(255,255,255,0.55);
    margin-bottom: 16px;
  }
  .hero-title {
    font-family: var(--font-display);
    font-size: clamp(28px, 4vw, 52px);
    font-weight: 900;
    color: var(--primary);
    line-height: 1.12;
    margin-bottom: 10px;
  }
  .hero-title span {
    color: rgba(255,255,255,0.55);
    display: block;
    font-size: 0.52em;
    font-weight: 400;
    letter-spacing: 0.08em;
    margin-top: 6px;
  }
  .hero-tagline {
    font-size: 15px;
    color: rgba(255,255,255,0.78);
    margin: 20px 0 32px;
    max-width: 520px;
    line-height: 1.7;
  }
  .hero-tagline strong { color: #fff; }
  .hero-buttons {
    display: flex;
    gap: 14px;
    flex-wrap: wrap;
  }
  .btn {
    display: inline-block;
    padding: 13px 30px;
    border-radius: 4px;
    font-family: var(--font-body);
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-decoration: none;
    transition: transform 0.2s, box-shadow 0.2s, background 0.2s;
    cursor: pointer;
    border: none;
  }
  .btn:hover { transform: translateY(-2px); box-shadow: 0 8px 24px var(--shadow-hover); }
  .btn-primary { background: var(--primary); color: var(--secondary-dark); }
  .btn-primary:hover { background: var(--primary-dark); }
  .btn-outline { background: transparent; color: var(--primary); border: 2px solid rgba(255,255,255,0.4); }
  .btn-outline:hover { background: rgba(255,255,255,0.12); border-color: #fff; }

  .hero-image-wrap {
    display: flex;
    justify-content: center;
    align-items: center;
  }
  .hero-image-wrap img {
    width: 100%;
    max-width: 500px;
    border-radius: 8px;
    box-shadow: 0 20px 60px rgba(0,0,0,0.4);
    border: 3px solid rgba(255,255,255,0.12);
  }

  /* ── TRUST BAR ── */
  .trust-bar {
    background: var(--primary);
    border-bottom: 1px solid var(--border);
    padding: 0;
  }
  .trust-bar-inner {
    max-width: 1800px;
    margin: 0 auto;
    padding: 0 24px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
  }
  .trust-item {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 22px 20px;
    border-right: 1px solid var(--border);
  }
  .trust-item:last-child { border-right: none; }
  .trust-icon {
    width: 44px;
    height: 44px;
    background: var(--secondary);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    color: #fff;
    font-size: 18px;
  }
  .trust-label { font-weight: 600; font-size: 13px; color: var(--text); line-height: 1.3; }
  .trust-label small { display: block; font-weight: 400; font-size: 11px; color: var(--text-muted); margin-top: 2px; }

  /* ── SECTION TITLES ── */
  .section-header {
    text-align: center;
    margin-bottom: 48px;
  }
  .section-eyebrow {
    display: inline-block;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--secondary);
    margin-bottom: 10px;
  }
  .section-title {
    font-family: var(--font-display);
    font-size: clamp(24px, 3vw, 38px);
    font-weight: 700;
    color: var(--text);
    line-height: 1.2;
  }
  .section-title-light { color: var(--primary); }
  .section-divider {
    width: 52px;
    height: 3px;
    background: var(--secondary);
    margin: 14px auto 0;
    border-radius: 2px;
  }

  /* ── ABOUT SECTION ── */
  .about-section {
    padding: 80px 0;
    background: var(--bg);
  }
  .about-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: start;
    max-width: 1800px;
    margin: 0 auto;
    padding: 0 24px;
  }
  .about-text {}
  .about-text p {
    color: var(--text);
    font-size: 15px;
    line-height: 1.8;
    margin-bottom: 18px;
  }
  .about-stat-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-top: 32px;
  }
  .about-stat {
    background: var(--bg-alt);
    border-left: 4px solid var(--secondary);
    padding: 18px 20px;
    border-radius: 0 6px 6px 0;
  }
  .about-stat-num {
    font-family: var(--font-display);
    font-size: 28px;
    font-weight: 700;
    color: var(--secondary);
    line-height: 1;
    margin-bottom: 4px;
  }
  .about-stat-label {
    font-size: 12px;
    color: var(--text-muted);
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }
  .about-image-wrap img {
    width: 100%;
    border-radius: 8px;
    box-shadow: 0 8px 40px var(--shadow);
    display: block;
  }
  .about-calendar { margin-top: 24px; }
  .about-calendar img {
    width: 100%;
    border-radius: 6px;
    box-shadow: 0 4px 20px var(--shadow);
  }

  /* ── PRODUCTS SECTION ── */
  .products-section {
    padding: 80px 0;
    background: var(--bg-alt);
  }

  .category-tabs {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    justify-content: center;
    margin-bottom: 48px;
  }
  .cat-tab {
    padding: 9px 22px;
    border-radius: 24px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    border: 2px solid var(--border);
    background: var(--primary);
    color: var(--text-muted);
    transition: all 0.2s;
    font-family: var(--font-body);
    letter-spacing: 0.04em;
  }
  .cat-tab:hover, .cat-tab.active {
    background: var(--secondary);
    border-color: var(--secondary);
    color: #fff;
  }

  .product-panels {}
  .product-panel { display: none; }
  .product-panel.active { display: block; }

  .product-category-block {
    background: var(--primary);
    border-radius: 10px;
    overflow: hidden;
    margin-bottom: 24px;
    box-shadow: 0 2px 12px var(--shadow);
    transition: box-shadow 0.2s;
  }
  .product-category-block:hover { box-shadow: 0 6px 24px var(--shadow-hover); }

  .prod-cat-header {
    background: var(--secondary-dark);
    color: #fff;
    padding: 16px 24px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    font-family: var(--font-display);
    font-size: 17px;
    font-weight: 600;
    user-select: none;
  }
  .prod-cat-header:hover { background: var(--secondary); }
  .prod-cat-toggle {
    width: 24px;
    height: 24px;
    background: rgba(255,255,255,0.15);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    transition: transform 0.3s;
  }
  .prod-cat-header.open .prod-cat-toggle { transform: rotate(45deg); }

  .prod-cat-body {
    padding: 20px 24px 24px;
    display: none;
  }
  .prod-cat-body.open { display: block; }

  .prod-sub-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--secondary);
    margin: 16px 0 10px;
    padding-bottom: 6px;
    border-bottom: 1px solid var(--border);
  }
  .prod-sub-label:first-child { margin-top: 0; }

  .prod-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 8px;
    margin-bottom: 8px;
  }
  .prod-link {
    display: block;
    padding: 10px 14px;
    background: var(--bg-alt);
    border: 1px solid var(--border);
    border-radius: 6px;
    text-decoration: none;
    color: var(--text);
    font-size: 13px;
    font-weight: 600;
    transition: background 0.2s, border-color 0.2s, transform 0.2s, box-shadow 0.2s;
    font-family: var(--font-body);
    line-height: 1.3;
  }
  .prod-link:hover {
    background: var(--secondary);
    border-color: var(--secondary);
    color: #fff;
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(143,0,0,0.25);
  }
  .prod-link-cat {
    display: block;
    padding: 10px 14px;
    background: var(--secondary-dark);
    border: 1px solid var(--secondary-dark);
    border-radius: 6px;
    text-decoration: none;
    color: #fff;
    font-size: 13px;
    font-weight: 600;
    transition: background 0.2s, transform 0.2s, box-shadow 0.2s;
    font-family: var(--font-body);
  }
  .prod-link-cat:hover {
    background: var(--secondary-light);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(143,0,0,0.3);
  }

  /* ── INFO BLOCKS ── */
  .info-section {
    padding: 80px 0;
    background: var(--secondary-dark);
  }
  .info-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
    max-width: 1800px;
    margin: 0 auto;
    padding: 0 24px;
  }
  .info-card {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 10px;
    padding: 32px 24px;
    text-align: center;
    transition: background 0.2s, transform 0.2s, box-shadow 0.2s;
  }
  .info-card:hover {
    background: rgba(255,255,255,0.11);
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(0,0,0,0.25);
  }
  .info-card-icon {
    font-size: 36px;
    margin-bottom: 16px;
  }
  .info-card-title {
    font-family: var(--font-display);
    font-size: 17px;
    font-weight: 600;
    color: #fff;
    margin-bottom: 10px;
  }
  .info-card-text {
    font-size: 13px;
    color: rgba(255,255,255,0.65);
    line-height: 1.65;
  }

  /* ── BRANCHES SECTION ── */
  .branches-section {
    padding: 80px 0;
    background: var(--bg);
  }
  .branches-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 32px;
    max-width: 1800px;
    margin: 0 auto;
    padding: 0 24px;
  }
  .branch-card {
    background: var(--primary);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 32px;
    box-shadow: 0 2px 12px var(--shadow);
    transition: transform 0.2s, box-shadow 0.2s;
    position: relative;
    overflow: hidden;
  }
  .branch-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    background: var(--secondary);
  }
  .branch-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 32px var(--shadow-hover);
  }
  .branch-name {
    font-family: var(--font-display);
    font-size: 19px;
    font-weight: 700;
    color: var(--secondary-dark);
    margin-bottom: 12px;
  }
  .branch-detail {
    font-size: 14px;
    color: var(--text-muted);
    line-height: 1.7;
  }
  .branch-detail strong { color: var(--text); font-weight: 600; }

  /* ── FOOTER ── */
  footer {
    background: var(--bg-dark);
    color: rgba(255,255,255,0.8);
    padding: 60px 0 0;
  }
  .footer-grid {
    max-width: 1800px;
    margin: 0 auto;
    padding: 0 24px;
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 48px;
    padding-bottom: 48px;
  }
  .footer-brand {}
  .footer-brand-name {
    font-family: var(--font-display);
    font-size: 20px;
    font-weight: 700;
    color: #fff;
    margin-bottom: 12px;
  }
  .footer-brand-text {
    font-size: 13px;
    color: rgba(255,255,255,0.55);
    line-height: 1.7;
    margin-bottom: 20px;
  }
  .footer-contact-item {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    font-size: 13px;
    color: rgba(255,255,255,0.65);
    margin-bottom: 10px;
    line-height: 1.5;
  }
  .footer-contact-icon { color: var(--secondary-light); font-size: 14px; margin-top: 2px; flex-shrink: 0; }

  .footer-col-title {
    font-family: var(--font-display);
    font-size: 14px;
    font-weight: 700;
    color: #fff;
    margin-bottom: 18px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }
  .footer-links { list-style: none; }
  .footer-links li { margin-bottom: 9px; }
  .footer-links a {
    font-size: 13px;
    color: rgba(255,255,255,0.55);
    text-decoration: none;
    transition: color 0.2s;
  }
  .footer-links a:hover { color: #fff; }

  .footer-bottom {
    background: rgba(0,0,0,0.4);
    text-align: center;
    padding: 18px 24px;
    font-size: 12px;
    color: rgba(255,255,255,0.35);
    border-top: 1px solid rgba(255,255,255,0.06);
    letter-spacing: 0.04em;
  }

  /* ── RESPONSIVE ── */
  @media (max-width: 1100px) {
    .trust-bar-inner { grid-template-columns: repeat(2, 1fr); }
    .trust-item:nth-child(2) { border-right: none; }
    .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
    .info-grid { grid-template-columns: repeat(2, 1fr); }
  }
  @media (max-width: 800px) {
    .hero-content { grid-template-columns: 1fr; gap: 32px; }
    .hero-image-wrap { display: none; }
    .about-grid { grid-template-columns: 1fr; }
    .branches-grid { grid-template-columns: 1fr; }
    .trust-bar-inner { grid-template-columns: 1fr 1fr; }
    .footer-grid { grid-template-columns: 1fr; gap: 28px; }
    .info-grid { grid-template-columns: 1fr 1fr; }
    .nav-links li:not(:first-child):not(:last-child) { display: none; }
    .prod-grid { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); }
  }
  @media (max-width: 500px) {
    .trust-bar-inner { grid-template-columns: 1fr; }
    .trust-item { border-right: none; border-bottom: 1px solid var(--border); }
    .info-grid { grid-template-columns: 1fr; }
    .about-stat-grid { grid-template-columns: 1fr; }
  }

